import java.util.NoSuchElementException;
import java.util.Scanner;

public class Test {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        boolean needSecond = false;
        while (s.hasNextLine()) {
            String line = s.nextLine();
            if (needSecond) {
                System.out.println(TextDocumentAnalysis.input(line));
            }
            needSecond = !needSecond;
        }
        if (needSecond) {
            throw new NoSuchElementException();
        }
        s.close();
    }
}

class TextDocumentAnalysis {
    public static String input(String str) {
        int max = 0;
        int words = 0;
        boolean open = false;
        int n = str.length();
        int i = 0;
        while (i < n) {
            char c = str.charAt(i);
            if (c == '_' || c == '(' || c == ')') {
                if (c == '(') open = true;
                else if (c == ')') open = false;
                i++;
            } else {
                int start = i;
                while (i < n && str.charAt(i) != '_' && str.charAt(i) != '(' && str.charAt(i) != ')') {
                    i++;
                }
                int len = i - start;
                if (i < n) {
                    char d = str.charAt(i);
                    if (d == '(') {
                        if (len > max) max = len;
                        open = true;
                    } else if (d == ')') {
                        words++;
                        open = false;
                    } else {
                        if (open) words++;
                        else if (len > max) max = len;
                    }
                } else {
                    if (open) words++;
                    else if (len > max) max = len;
                }
            }
        }
        return max + " " + words;
    }
}
